pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address player) public {
        vm.assume(player != address(0));
        // Fuzzer explores different numbers of plays.
        // We pick a single play because the invariant already breaks after one winning play.
        uint256 ticketAmount = 10;
        vm.deal(player, ticketAmount);
        vm.prank(player);
        // The fuzzed player calls play() once.
        // We need to know whether they won; we observe pot afterwards.
        try c.play{value: ticketAmount}() {
            // call succeeded; a win sets pot = 0, a loss leaves pot at the accumulated value.
            // The invariant: after a call where player won (random == 0), pot == 0.
            // After a call where player lost (random == 1), pot == ticketAmount (since no payout).
            // In the reference contract, pot == 0 iff the player won.
            // In the buggy contract, pot += 0 means pot is always 0 after any play,
            // so pot == 0 even when the player loses.
            // General rule: if pot == 0 then the contract's pot must equal ticketAmount * (number of wins that reset it).
            // Simpler invariant that holds for reference but fails for bug after a loss:
            // pot is either 0 or ticketAmount. The bug makes it always 0.
            // After a single call that does not win, reference has pot == ticketAmount, bug has pot == 0.
            // We assert: pot == ticketAmount if and only if the call did not produce a payout.
            // Since we cannot observe whether the player won directly (no event), we use the following:
            // In reference, pot == ticketAmount after a loss, pot == 0 after a win.
            // In bug, pot == 0 always.
            // The property: after the call, either pot == 0 or pot == ticketAmount. This holds for reference always.
            // In bug, pot is always 0, which still satisfies the disjunction.
            // So we need a stronger property that references pot balance.
            // Actually the balance of the contract reflects payments. In reference, after a loss, pot = ticketAmount and contract balance = ticketAmount.
            // After a win, pot = 0 and contract balance = 0 (because bank fee + winner payout = pot - fee + fee = pot).
            // In bug, after a loss, pot = 0 but contract balance = ticketAmount (since pot += 0, the ether stays).
            // After a win, pot = 0 and contract balance = fee + (pot - fee) with pot=0 so payout = -fee? That's a problem: pot - fee underflows.
            // So a loss in bug creates a discrepancy: pot == 0 but address(c).balance == ticketAmount.
            // The invariant: pot == address(c).balance always (since pot tracks incoming payments that haven't been paid out).
            // Reference: after loss: pot = ticket, balance = ticket; after win: pot=0, balance=0 (bank got fee, player got pot-fee).
            // Bug: after loss: pot = 0, balance = ticket; invariant broken.
            // This invariant holds in reference for any sequence of plays, including wins.
            assertEq(c.pot(), address(c).balance, "pot should equal contract balance");
        } catch {
            // If call reverts (should not under normal conditions), we don't assert anything.
        }
    }
}

