import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 n, uint256 seed) public {
        // Restrict to a sensible number of calls to keep fuzzing practical
        n = bound(n, 1, 20);
        // seed for controlling win outcomes via block difficulty / timestamp manipulation
        vm.warp(seed % 10000 + 1);
        vm.roll(seed % 10000 + 1);

        // Track the expected pot: sum of ticket amounts since last win payout
        uint256 expectedPot = 0;
        // Simulate n plays, possibly manipulating the outcome via block parameters
        for (uint256 i = 0; i < n; i++) {
            // Update block parameters to influence the random outcome
            vm.warp(block.timestamp + 1);
            vm.roll(block.number + 1);

            address player = address(uint160(uint256(keccak256(abi.encode(seed, i)))));
            vm.deal(player, 10);
            vm.prank(player);
            try c.play{value: 10}() {
                uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
                expectedPot += 10;
                if (random == 0) {
                    // win: pot should reset to 0
                    expectedPot = 0;
                }
            } catch {
                // play revert means no state change in expected model
            }
        }

        // Assert that the actual pot equals expectedPot (which is 0 if last call was a win, else accumulated)
        assertEq(c.pot(), expectedPot, "pot must reflect tickets since last win");
    }
}

