        plays = bound(plays, 0, 100);
        uint ticketsSinceLastWin = 0;
        bool hadWin = false;
        for (uint i = 0; i < plays; i++) {
            address player = address(uint160(1000 + i)); // unique player per iteration, deterministic but fuzzed via plays
            vm.deal(player, 1 ether);
            vm.prank(player);
            try c.play{value: 10}() {
                // If we get here, the play succeeded (random may be 0 or 1)
                // We need to check if a win occurred. Since pot changes are observable,
                // we can infer from pot value. Correct contract resets pot to 0 on win.
                // We track tickets since last win externally.
                ticketsSinceLastWin += 10;
                uint currentPot = c.pot();
                if (currentPot < ticketsSinceLastWin) {
                    // A win reset the pot.
                    hadWin = true;
                    ticketsSinceLastWin = currentPot;
                }
                // Assert: pot never exceeds tickets since last win
                assertTrue(currentPot <= ticketsSinceLastWin);
            } catch {
                // Play failed (msg.value != 10), skip this iteration. ticketsSinceLastWin unchanged.
