pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 playBeforeWin, uint256 playAfterWin) public {
        // Keep play counts within reasonable range
        playBeforeWin = bound(playBeforeWin, 0, 10);
        playAfterWin = bound(playAfterWin, 0, 10);

        // We need at least one play before triggering a win to accumulate pot
        vm.assume(playBeforeWin > 0);

        address player = address(0xB0b);
        vm.deal(player, (playBeforeWin + playAfterWin + 2) * 10 ether);

        // Play some tickets before a forced win
        vm.startPrank(player);
        for (uint i = 0; i < playBeforeWin; i++) {
            // We want to avoid accidentally triggering random==0 during these,
            // so we manipulate timestamp/difficulty indirectly by not forcing a win yet.
            c.play{value: 10}();
            vm.roll(block.number + 1); // change block context so random may vary
        }

        // Now force a win: we know random uses block.timestamp and block.difficulty.
        // We set block parameters so that uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2 == 0
        // We can achieve this by iterating until we find a block that yields a win, but fuzzer provides counts.
        // Rather than brute-forcing a favorable block, we leverage that the fuzzer may find a sequence where a win occurs.
        // To guarantee a win, we can simulate playing with param-controlled random, but here we rely on fuzzer finding a scenario.
        // Actually we must ensure a win occurs; we'll just play and assume the fuzzer will explore sequences where win did happen.
        // To increase chance, we can try several blocks until win:
        bool winOccurred = false;
        for (uint j = 0; j < 20; j++) {
            uint rand = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
            if (rand == 0) {
                // Before playing, record pot
                c.play{value: 10}();
                winOccurred = true;
                break;
            } else {
                vm.roll(block.number + 1);
            }
        }
        vm.stopPrank();

        // If no win occurred, we can't test the property; but the fuzzer may still find such inputs.
        vm.assume(winOccurred);

        // Record pot after the win (should be 0 in correct contract)
        uint256 potAfterWin = c.pot();

        // Now play additional tickets
        vm.startPrank(player);
        for (uint k = 0; k < playAfterWin; k++) {
            c.play{value: 10}();
            vm.roll(block.number + 1);
        }
        vm.stopPrank();

        // After these plays, the pot should be exactly playAfterWin * 10 (the tickets added after the reset),
        // because win resets pot to 0 in correct contract.
        // The buggy one adds to previous pot (which was not reset), so pot will be larger.
        uint256 expectedPotAfterAdditionalPlays = playAfterWin * 10;
        assertTrue(c.pot() == expectedPotAfterAdditionalPlays);
    }
}

