pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 seed) public {
        // Ensure we have a funded sender
        address player = makeAddr("player");
        vm.deal(player, 10 ether);

        // We need the random to be 0 (win branch), which depends on timestamp and difficulty.
        // The fuzzer can manipulate these via vm.warp / vm.roll to find a winning seed.
        // We bound the timestamp and difficulty to reasonable ranges.
        uint256 ts = uint256(seed) % 10000000000;
        uint256 diff = (uint256(seed) >> 96) % 10000000000;
        vm.warp(ts);
        vm.roll(diff);

        // Calculate if this input leads to random == 0. If not, the assertion inside the try/catch will
        // simply check that after a losing call pot stays unchanged (which holds in both versions).
        // But we need the invariant to hold ALWAYS, so our assertion must be true regardless of the branch.
        // The universal rule: after ANY play() call that does NOT revert, pot is exactly 0 if a win occurred,
        // and pot is its old value + 10 if a loss occurred.
        // We capture the pre-state.
        uint256 potBefore = c.pot();

        vm.prank(player);
        try c.play{value: 10}() {
            // Call did not revert.
            uint256 potAfter = c.pot();
            uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
            if (random == 0) {
                // Winning branch: pot must become 0.
                assertEq(potAfter, 0);
            } else {
                // Losing branch: pot = potBefore + 10
                assertEq(potAfter, potBefore + 10);
            }
        } catch {
            // The call reverted (e.g., bank transfer might fail, but we didn't manipulate bank).
            // In this case, state must remain unchanged.
            assertEq(c.pot(), potBefore);
        }
    }
}

